import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Basic date format check (YYYY-MM-DD)
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column whitelist
        String safeSortCol = sanitizeSortColumn(sortCol);

        // Build query - filter parameter allows flexible WHERE clause additions
        String query = buildReportQuery(reportType, startDate, endDate, safeSortCol, customFilter);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end,
                                     String sortCol, String filter) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(type);
        sb.append(" WHERE created_at >= '").append(start).append("'");
        sb.append(" AND created_at <= '").append(end).append("'");

        if (filter != null && !filter.isEmpty()) {
            // Custom filter for advanced users - supports arbitrary conditions
            sb.append(" AND (").append(filter).append(")");
        }

        sb.append(" ORDER BY ").append(sortCol);
        sb.append(" LIMIT 1000");
        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        return type != null && type.matches("^(sales|inventory|users|audit|finance)$");
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private String sanitizeSortColumn(String col) {
        String[] allowed = {"created_at", "id", "amount", "status", "name"};
        for (String a : allowed) {
            if (a.equals(col)) return col;
        }
        return "created_at";
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(rs.getString(i)).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
